"""Make a comparison page from real existing Unity captures; no invented after frames."""
from pathlib import Path
import json,sys,html
root=Path('/Users/adnanyonathan/Documents/Codex/2026-09-20/wh/outputs/iphone-golf-simulator')
checkpoint=int(sys.argv[1]);folder=root/sys.argv[2];proof=root/'proof/full-visual-overhaul/golf'
scenes=[
 {'hole':12,'name':'Coastal / Cliffside','reference':'reference-coastal.png','shot':'gameplay','secondary':'preview','baseline':'gameplay','note':'Irregular bevelled cliff shoulders, richer water, groomed turf, lower white cumulus, bridge/lighthouse finishing and layered trees are implemented. Illustrated density, limestone relief and scene composition remain below the target. Compare the actual near view as well as the island overview.'},
 {'hole':19,'name':'Temple / Jungle','reference':'reference-temple.png','shot':'preview','secondary':'approach','baseline':'aerial','note':'Actual warm temple stone courses, pilasters, urns/vines, drooping feathered palms and separate cliff render meshes are visible. Plant masses remain thinner and sparser than the target. Camera angles differ; this is an art-direction comparison, not identical pixel registration.'},
 {'hole':21,'name':'Volcanic / Magma','reference':'reference-volcanic.png','shot':'gameplay','secondary':'showcase_085','baseline':'gameplay','note':'Broad eroded decorative crater walls, cool lava interiors, hot flowing channels and continuous tapered falls replace the old terraces and spoke strips. Basalt variation and target mood remain partial. The close showcase frame is the direct fall-to-pool contact review.'}
]
sections=[]
for s in scenes:
 n=s['hole'];actual=folder/f'hole{n:02}_{s["shot"]}.png';secondary=folder/f'hole{n:02}_{s["secondary"]}.png'
 if not actual.exists() or not secondary.exists():raise SystemExit('Actual comparison incomplete: '+str(actual)+' / '+str(secondary))
 ar='../'+str(actual.relative_to(root/'proof/full-visual-overhaul'));sr='../'+str(secondary.relative_to(root/'proof/full-visual-overhaul'))
 sections.append(f'''<section><h2>{html.escape(s['name'])}</h2><p>{html.escape(s['note'])}</p><div class="grid"><figure><figcaption>Original Unity baseline</figcaption><div class="frame"><img src="../baseline-golf/hole{n}_{s['baseline']}.png"></div></figure><figure><figcaption>GPT Image concept target</figcaption><div class="frame target"><img src="{s['reference']}"></div></figure><figure><figcaption>Actual Unity source {checkpoint} · {s['shot']}</figcaption><div class="frame actual"><a href="{ar}"><img src="{ar}"></a><img class="overlay" src="{s['reference']}"></div></figure></div><details><summary>Inspect actual {s['secondary']} close/overview</summary><a href="{sr}"><img class="secondary" src="{sr}"></a></details></section>''')
(proof/'reference-comparison.html').write_text('''<!doctype html><html><head><meta charset="utf-8"><title>Golf actual versus concept</title><style>body{margin:0;padding:28px;background:#101c24;color:#e7f1ef;font:16px system-ui}h1{font-size:26px;margin:0 0 8px}p{max-width:1200px;line-height:1.6;color:#bacbc8}section{margin:30px 0;border-top:1px solid #425a63;padding-top:20px}.grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:18px}figure{margin:0}figcaption{margin:0 0 10px;color:#b9d0d4;font-size:14px}.frame{position:relative;background:#23343d;height:680px}.frame img{width:100%;height:100%;object-fit:contain}.overlay{position:absolute;inset:0;opacity:0;pointer-events:none}.target{border:1px solid #347969}.actual{border:1px solid #856640}details{margin:18px 0}.secondary{max-width:100%;max-height:850px}summary{cursor:pointer;padding:12px;background:#22363c}input{accent-color:#5fdfc6;vertical-align:middle}@media(max-width:900px){.grid{grid-template-columns:1fr}.frame{height:620px}}</style></head><body><h1>Golf actual versus concept</h1><p>The concept images are aspirational GPT Image targets. Every after photo on this page is an unedited actual Unity capture from '''+html.escape(str(folder.relative_to(root)))+'''. Exact concept parity remains partial. Source hashes, physics equality and editor frame costs are separate gates in GOLF_GATE.md. The overlay helps compare visual mass and mood; framing differs.</p><label>Concept overlay on actual <input id="alpha" type="range" min="0" max="100" value="0"></label><span id="percentage">0%</span>'''+''.join(sections)+'''<script>const a=document.getElementById('alpha');a.oninput=()=>{document.querySelectorAll('.overlay').forEach(x=>x.style.opacity=a.value/100);document.getElementById('percentage').textContent=a.value+'%'};</script></body></html>''')
print(json.dumps({'checkpoint':checkpoint,'page':str(proof/'reference-comparison.html'),'actual_scenes':3,'status':'PARTIAL concept parity; direct actual images, not completion claim'}))
